const assert = require('node:assert/strict');
const { EventService } = require('../.build/service');

// A test Source/Lease using the open, read and close interface from src/source.ts.
function fixture(values, { read, close, mapper } = {}) {
  const calls = { opens: 0, reads: 0, closes: 0 };
  const source = {
    async open() {
      calls.opens++;
      return {
        async read() {
          calls.reads++;
          return read ? read(calls.reads) : values.shift();
        },
        async close() {
          calls.closes++;
          if (close) await close();
        },
      };
    },
  };
  return { calls, stream: new EventService(source, mapper).stream() };
}

async function rejectsWith(promise, expected) {
  let rejected = false;
  try {
    await promise;
  } catch (error) {
    rejected = true;
    assert.strictEqual(error, expected);
  }
  assert.equal(rejected, true, 'expected rejection');
}

async function main() {
  // Opening is lazy, and returning an unopened generator does nothing.
  {
    const { stream, calls } = fixture(['a', null]);
    assert.deepEqual(calls, { opens: 0, reads: 0, closes: 0 });
    assert.deepEqual(await stream.return(), { value: undefined, done: true });
    assert.deepEqual(calls, { opens: 0, reads: 0, closes: 0 });
  }

  // Ordered mapping, exactly one read per next(), including exhaustion.
  {
    const { stream, calls } = fixture(['a', 'b', null]);
    assert.deepEqual(await stream.next(), { value: 'A', done: false });
    assert.deepEqual(calls, { opens: 1, reads: 1, closes: 0 });
    await Promise.resolve();
    assert.equal(calls.reads, 1);
    assert.deepEqual(await stream.next(), { value: 'B', done: false });
    assert.deepEqual(calls, { opens: 1, reads: 2, closes: 0 });
    assert.deepEqual(await stream.next(), { value: undefined, done: true });
    assert.deepEqual(calls, { opens: 1, reads: 3, closes: 1 });
    await stream.next();
    await stream.return();
    assert.deepEqual(calls, { opens: 1, reads: 3, closes: 1 });
  }

  // Normal exhaustion, empty sources, break and explicit return all close once.
  for (const exit of ['exhaustion', 'empty', 'break', 'return']) {
    const { stream, calls } = fixture(exit === 'empty' ? [null] : ['a', 'b', null]);
    if (exit === 'return') {
      await stream.next();
      assert.deepEqual(await stream.return('finished'), { value: 'finished', done: true });
    } else {
      const found = [];
      for await (const value of stream) {
        found.push(value);
        if (exit === 'break') break;
      }
      assert.deepEqual(found, exit === 'empty' ? [] : exit === 'break' ? ['A'] : ['A', 'B']);
    }
    assert.deepEqual(calls, {
      opens: 1,
      reads: exit === 'exhaustion' ? 3 : 1,
      closes: 1,
    });
    await stream.return();
    assert.equal(calls.closes, 1);
  }

  // A close error propagates when there is no prior failure, on every exit path.
  for (const exit of ['exhaustion', 'break', 'return']) {
    const closeError = new Error('close');
    const { stream, calls } = fixture(['a', null], {
      close: () => { throw closeError; },
    });
    const consume = async () => {
      if (exit === 'return') {
        await stream.next();
        await stream.return();
      } else {
        for await (const value of stream) {
          if (exit === 'break') break;
        }
      }
    };
    await rejectsWith(consume(), closeError);
    assert.deepEqual(calls, { opens: 1, reads: exit === 'exhaustion' ? 2 : 1, closes: 1 });
    await stream.return();
    assert.equal(calls.closes, 1);
  }

  // Read, mapper and injected errors win over close errors, even if falsy.
  for (const failure of ['read', 'mapper', 'throw']) {
    for (const closeFails of [false, true]) {
      for (const original of [new Error(failure), undefined, null]) {
        const { stream, calls } = fixture(['a', null], {
          read: failure === 'read' ? () => { throw original; } : undefined,
          mapper: failure === 'mapper' ? () => { throw original; } : undefined,
          close: closeFails ? () => { throw new Error('close'); } : undefined,
        });
        if (failure === 'throw') await stream.next();
        await rejectsWith(failure === 'throw' ? stream.throw(original) : stream.next(), original);
        assert.deepEqual(calls, { opens: 1, reads: 1, closes: 1 });
        await stream.next();
        await stream.return();
        assert.equal(calls.closes, 1);
      }
    }
  }

  // Failure to open creates no lease to close.
  {
    const openError = new Error('open');
    let opens = 0;
    const stream = new EventService({ open: async () => { opens++; throw openError; } }).stream();
    assert.equal(opens, 0);
    await rejectsWith(stream.next(), openError);
    await stream.return();
    assert.equal(opens, 1);
  }
}

module.exports = main();

